<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3">Parties</h1><p class="text-secondary">Customers, suppliers and referees.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#partyModal">Add Party</button></div><div class="card shadow-sm"><div class="card-body"><div class="row g-2 mb-3"><div class="col-md-3"><select id="partyType" class="form-select"><option value="CUSTOMER">Customers</option><option value="SUPPLIER">Suppliers</option><option value="REFEREE">Referees</option></select></div><div class="col-md-5"><input id="partySearch" class="form-control" placeholder="Search"></div></div><div class="table-responsive"><table class="table" id="partyTable"><thead><tr><th>Code</th><th>Name</th><th>Phone</th><th>Credit</th><th>Status</th></tr></thead><tbody></tbody></table></div></div></div><div class="modal fade" id="partyModal"><div class="modal-dialog"><form class="modal-content" id="partyForm"><div class="modal-header"><h5>Add Party</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input name="code" class="form-control mb-2" placeholder="Code" required><select name="party_type" class="form-select mb-2"><option>CUSTOMER</option><option>SUPPLIER</option><option>REFEREE</option></select><input name="name" class="form-control mb-2" placeholder="Name" required><input name="phone" class="form-control mb-2" placeholder="Phone"><textarea name="address" class="form-control mb-2" placeholder="Address"></textarea><select name="allow_credit" class="form-select mb-2"><option value="0">Credit not allowed</option><option value="1">Credit allowed</option></select><input name="credit_limit" class="form-control mb-2" value="0.00" placeholder="Credit limit"><input name="opening_balance" class="form-control" value="0.00" placeholder="Opening balance"></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div><script>$(function(){function load(){ $.getJSON('<?=e(url('/parties/data'))?>',{type:$('#partyType').val(),search:$('#partySearch').val()},function(r){let b=$('#partyTable tbody').empty();r.data.rows.forEach(x=>b.append('<tr><td>'+ $('<span>').text(x.code).html()+'</td><td>'+ $('<span>').text(x.name).html()+'</td><td>'+ $('<span>').text(x.phone||'').html()+'</td><td>'+Number(x.credit_limit).toFixed(2)+'</td><td>'+(x.active?'Active':'Inactive')+'</td></tr>'));});}$('#partyType,#partySearch').on('change keyup',load);$('#partyForm').on('submit',function(e){e.preventDefault();$.post('<?=e(url('/parties'))?>',$(this).serialize()).done(function(r){if(r.ok)location.reload();else alert(r.message);}).fail(function(x){alert(x.responseJSON?.message||'Save failed');});});load();});</script>